import clsx from 'clsx';
import React from 'react';

import {
  suggestionGroupCSS,
  suggestionGroupListCSS,
} from './SuggestionGroup.sty.js';
import { _useAriaLabelingProps } from '../../../core/hooks/useAriaLabelingProps.js';
import type { AriaLabelingProps } from '../../../core/types/a11y-props.js';
import type { DataTestId } from '../../../core/types/data-props.js';
import type { StylingProps } from '../../../core/types/styling-props.js';
import type { WithChildren } from '../../../core/types/with-children.js';

export type FilterFieldSuggestionGroupProps = WithChildren &
  AriaLabelingProps &
  StylingProps &
  DataTestId;

export const SuggestionGroup = (props: FilterFieldSuggestionGroupProps) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    ...remainingProps
  } = props;
  const ariaLabelingProps = _useAriaLabelingProps(remainingProps);

  return (
    <li
      data-testid={dataTestId}
      className={clsx(suggestionGroupCSS, consumerClassName)}
      style={consumerStyle}
    >
      <ul
        role="group"
        className={suggestionGroupListCSS}
        {...ariaLabelingProps}
      >
        {children}
      </ul>
    </li>
  );
};

SuggestionGroup.displayValue = 'FilterField.SuggestionGroup';
